.header__icon--menu {
    position: initial;
}

#Details-menu-drawer-container {
    display: none;
}

.menu-drawer {
    display: block !important;
    position: fixed;
    z-index: 3;
    bottom: 0;
    padding: 0;
    background-color: rgb(var(--color-background));
    overflow-x: hidden;
    -webkit-transition: -webkit-transform .25s cubic-bezier(0.8, 0, 0.2, 1));
    transition: -webkit-transform .25s cubic-bezier(0.8, 0, 0.2, 1);
    transition: transform .25s cubic-bezier(0.8, 0, 0.2, 1);
    transition: transform .25s cubic-bezier(0.8, 0, 0.2, 1), -webkit-transform .25s cubic-bezier(0.8, 0, 0.2, 1);
}

.js #Details-menu-drawer-container.open>.menu-drawer {
    transform: translateX(-100%);
}

#Details-menu-drawer-container.open .header__icon--menu::before {
    content: '';
    top: 100%;
    left: 0;
    height: calc(var(--viewport-height, 100vh) - (var(--header-bottom-position, 100%)));
    width: 100%;
    display: block;
    position: absolute;
    background: #fafafa;
}

.scrolled-past-header .menu-drawer {
    top: 47px;
}

@media screen and (min-width: 480px) {
    .scrolled-past-header .menu-drawer {
        top: 47px;
    }

    #Details-menu-drawer-container.open .header__icon--menu::before {
        background: rgba(var(--color-foreground), 0.4);
    }
}

.menu-drawer__inner-container {
    position: relative;
    height: 100%;
}

.menu-drawer__navigation-container {
    display: flex;
    flex-direction: column;
    align-content: space-between;
    overflow-y: auto;
    height: 100%;
}

.menu-drawer__navigation {
    padding: 3rem 0;
}

.menu-drawer__inner-submenu {
    height: 100%;
    overflow-x: hidden;
    overflow-y: auto;
}

.js .menu-drawer__menu li {
    margin-bottom: 0.2rem;
}

.menu-drawer__menu-item {
    text-decoration: none;
}

.menu-drawer summary.menu-drawer__menu-item {
    padding-right: 5.2rem;
}

.menu-drawer__menu-item--active,
.menu-drawer__menu-item:focus,
.menu-drawer__close-button:focus,
.menu-drawer__menu-item:hover,
.menu-drawer__close-button:hover {
    color: rgb(var(--color-foreground));
    background-color: rgba(var(--color-foreground), 0.04);
}

.menu-drawer__menu-item--active:hover {
    background-color: rgba(var(--color-foreground), 0.08);
}

.js .menu-drawer__menu-item .icon-caret {
    display: none;
}

.menu-drawer__menu-item>.icon-arrow {
    position: absolute;
    right: 3rem;
    top: 50%;
    transform: translateY(-50%);
}

.js .menu-drawer__submenu {
    width: 100%;
    background-color: rgb(var(--color-background));
    z-index: 1;
}

.js .menu-drawer__submenu .menu-drawer__submenu {
    overflow-y: auto;
}

.menu-drawer__close-button {
    display: none;
    margin-top: 1.5rem;
    padding: 1.2rem 2.6rem 1.2rem 3rem;
    text-decoration: none;
    display: flex;
    align-items: center;
    font-size: 1.4rem;
    width: 100%;
    background-color: transparent;
    font-family: var(--font-body-family);
    font-style: var(--font-body-style);
    text-align: left;
}

.menu-drawer__close-button .icon-arrow {
    transform: rotate(180deg);
    margin-right: 1rem;
}

.menu-drawer__utility-links {
    padding: 0;
    background-color: transparent;
    position: relative;
}

.header--has-social .menu-drawer__utility-links {
    padding: 2rem 3rem;
}

